using System;
using System.Runtime.InteropServices;

namespace TokenPrivilegeExample
{
    class Program
    {
        [DllImport("advapi32.dll", CharSet = CharSet.Auto, CallingConvention = CallingConvention.StdCall)]
        private static extern bool AdjustTokenPrivileges(IntPtr tokenHandle, int privilege, bool add);

        [DllImport("kernel32.dll", CharSet = CharSet.Auto, CallingConvention = CallingConvention.StdCall)]
